27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.server.ResponseStatusException;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
115	        owner.setTelephone(normalizedTelephone);
116	        owner.setEmail(normalizeEmail(owner.getEmail()));
117	        owner.setAddress(normalizeAddress(owner.getAddress()));
118	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
119	        if (effectiveRegistrationDate == null) {
120	            effectiveRegistrationDate = LocalDate.now();
121	        }
122	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
123	        owner.setRegistrationDate(effectiveRegistrationDate);
124	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
125	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
126	                "the maximum number of owners that may be created today has been reached");
127	        }
128	        if (isTelephoneInUse(normalizedTelephone, null)) {
129	            throw new ResponseStatusException(HttpStatus.CONFLICT,
130	                "telephone is already in use by another owner");
131	        }
132	        if (isEmailInUse(owner.getEmail(), null)) {
133	            throw new ResponseStatusException(HttpStatus.CONFLICT,
134	                "email is already in use by another owner");
135	        }
136	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
137	        if (!sharesHousehold
138	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress(), null)) {
139	            throw new ResponseStatusException(HttpStatus.CONFLICT,
140	                "another owner with the same last name already lives at this address");
141	        }
142	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
143	            throw new ResponseStatusException(HttpStatus.CONFLICT,
144	                "city has reached its maximum number of owners");
145	        }
146	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
147	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
148	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
149	        owner.setBulkSignupWarning(
150	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
151	        if (sharesHousehold) {
152	            this.clinicService.assignHousehold(owner);
153	        }
154	        this.clinicService.saveOwner(owner);
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
157	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
158	            ownerDto.getMembershipLevel());
159	        headers.setLocation(UriComponentsBuilder.newInstance()
160	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
161	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
167	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
168	        if (currentOwner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        currentOwner.setAddress(ownerFieldsDto.getAddress());
172	        currentOwner.setCity(ownerFieldsDto.getCity());
173	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
174	        currentOwner.setLastName(ownerFieldsDto.getLastName());
175	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
176	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
177	        this.clinicService.saveOwner(currentOwner);
178	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Transactional
183	    @Override
184	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
185	        Owner owner = this.clinicService.findOwnerById(ownerId);
186	        if (owner == null) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        this.clinicService.deleteOwner(owner);
190	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        HttpHeaders headers = new HttpHeaders();
201	        Pet pet = petMapper.toPet(petFieldsDto);
202	        owner.setId(ownerId);
203	        pet.setOwner(owner);
204	        pet.getType().setName(null);
205	        this.clinicService.savePet(pet);
206	        PetDto petDto = petMapper.toPetDto(pet);
207	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
208	            .buildAndExpand(pet.getId()).toUri());
209	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
215	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
216	        if (currentOwner != null) {
217	            Pet currentPet = this.clinicService.findPetById(petId);
218	            if (currentPet != null) {
219	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
220	                currentPet.setName(petFieldsDto.getName());
221	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
222	                this.clinicService.savePet(currentPet);
223	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
224	            }
225	        }
226	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
232	        HttpHeaders headers = new HttpHeaders();
233	        Visit visit = visitMapper.toVisit(visitFieldsDto);
234	        Pet pet = new Pet();
235	        pet.setId(petId);
236	        visit.setPet(pet);
237	        this.clinicService.saveVisit(visit);
238	        VisitDto visitDto = visitMapper.toVisitDto(visit);
239	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
240	            .buildAndExpand(visit.getId()).toUri());
241	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
242	    }
243	
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner != null) {
250	            Pet pet = owner.getPet(petId);
251	            if (pet != null) {
252	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    /**
259	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
260	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
261	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
262	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
263	     *
264	     * @param city     the owner's city
265	     * @param lastName the owner's last name
266	     * @return the assigned customer code
267	     */
268	    private String nextCustomerCode(String city, String lastName) {
269	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
270	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
271	        int sequence = countOwnersInCity(city) + 1;
272	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
273	    }
274	
275	    /**
276	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
277	     * owner's city already contains this many owners.
278	     */
279	    private static final int CITY_CAPACITY = 50;
280	
281	    /**
282	     * The maximum number of owners that may be created on a single day. A create is rejected with
283	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
284	     * {@code registrationDate}.
285	     */
286	    private static final int DAILY_CREATE_LIMIT = 100;
287	
288	    /**
289	     * The number of owners that must already have been created for the current day before a new
290	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
291	     * owners already carry today's {@code registrationDate}.
292	     */
293	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
294	
295	    /**
296	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
297	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
298	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
299	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
300	     * falls on a business day.
301	     *
302	     * @param date the effective registration date
303	     * @return the same date when it is a weekday, otherwise the following Monday
304	     */
305	    private static LocalDate rollToBusinessDay(LocalDate date) {
306	        return switch (date.getDayOfWeek()) {
307	            case SATURDAY -> date.plusDays(2);
308	            case SUNDAY -> date.plusDays(1);
309	            default -> date;
310	        };
311	    }
312	
313	    /**
314	     * Counts the existing owners whose {@code registrationDate} equals the given (already
315	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
316	     * business day. Called before a new owner is saved, so the returned value reflects the number of
317	     * owners created for that day prior to this create.
318	     *
319	     * @param date the adjusted business-day registration date to count against
320	     * @return the number of existing owners registered on that date
321	     */
322	    private int countOwnersRegisteredOn(LocalDate date) {
323	        return (int) this.clinicService.findAllOwners().stream()
324	            .filter(existing -> date.equals(existing.getRegistrationDate()))
325	            .count();
326	    }
327	
328	    /**
329	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
330	     *
331	     * @param city the city to count owners for
332	     * @return the number of existing owners in that city
333	     */
334	    private int countOwnersInCity(String city) {
335	        return (int) this.clinicService.findAllOwners().stream()
336	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
337	            .count();
338	    }
339	
340	    /**
341	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
342	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
343	     *
344	     * @param customerCode     the owner's assigned customer code
345	     * @param registrationDate the owner's registration date
346	     * @return the assigned membership number
347	     */
348	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
349	        String yy = String.format("%02d", registrationDate.getYear() % 100);
350	        return String.format("%s-M%s", customerCode, yy);
351	    }
352	
353	    /**
354	     * Counts the existing owners that already share the given first name and last name, comparing
355	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
356	     * the number of namesakes that existed prior to this create.
357	     *
358	     * @param firstName the new owner's first name
359	     * @param lastName  the new owner's last name
360	     * @return the number of existing owners with the same first and last name
361	     */
362	    private int countNamesakes(String firstName, String lastName) {
363	        int count = 0;
364	        for (Owner existing : this.clinicService.findAllOwners()) {
365	            if (firstName.equalsIgnoreCase(existing.getFirstName())
366	                && lastName.equalsIgnoreCase(existing.getLastName())) {
367	                count++;
368	            }
369	        }
370	        return count;
371	    }
372	
373	    /**
374	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
375	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
376	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
377	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
378	     * string is what gets stored and returned.
379	     *
380	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
381	     *
382	     * <p>Once in E.164 form the national-number length is validated against the country code: a
383	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
384	     * number exactly 10 (see {@link #COUNTRY_NATIONAL_LENGTHS}). Country codes without a configured
385	     * rule are accepted on the general 8-to-15 digit length alone.
386	     *
387	     * @param telephone the raw telephone value supplied by the client
388	     * @return the normalized E.164 telephone number
389	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
390	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
391	     *                                 after the {@code '+'}, or the wrong national-number length for
392	     *                                 its country code)
393	     */
394	    private static String normalizeTelephone(String telephone) {
395	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
396	        String digits;
397	        if (cleaned.startsWith("+")) {
398	            digits = cleaned.substring(1);
399	        } else {
400	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
401	            digits = "61" + national;
402	        }
403	        if (!digits.matches("[0-9]{8,15}")) {
404	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
405	                "telephone could not be normalized to a valid E.164 number");
406	        }
407	        validateNationalNumberLength(digits);
408	        return "+" + digits;
409	    }
410	
411	    /**
412	     * International dialling codes mapped to the exact number of national (subscriber) digits an
413	     * E.164 number for that country must carry: {@code +61} (Australia) requires 9 national digits
414	     * and {@code +1} (NANP) requires 10. Country codes absent from this map have no length rule.
415	     */
416	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
417	
418	    /**
419	     * Validates the national-number length of an E.164 number (its digits, without the leading
420	     * {@code '+'}) against its country code. The longest configured dialling code that prefixes the
421	     * number selects the rule; if none is configured the number passes (only the general 8-to-15
422	     * digit rule applies).
423	     *
424	     * @param digits the E.164 digits without the leading {@code '+'}
425	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
426	     *                                 digits does not match the country code's required length
427	     */
428	    private static void validateNationalNumberLength(String digits) {
429	        COUNTRY_NATIONAL_LENGTHS.keySet().stream()
430	            .filter(digits::startsWith)
431	            .max(Comparator.comparingInt(String::length))
432	            .ifPresent(code -> {
433	                int nationalLength = digits.length() - code.length();
434	                if (nationalLength != COUNTRY_NATIONAL_LENGTHS.get(code)) {
435	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
436	                        "telephone must have " + COUNTRY_NATIONAL_LENGTHS.get(code)
437	                            + " national digits for country code +" + code);
438	                }
439	            });
440	    }
441	
442	    /**
443	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
444	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
445	     *
446	     * @param telephone the stored telephone value, possibly {@code null}
447	     * @return the E.164 form, or the raw value when it cannot be normalized
448	     */
449	    private static String toComparableTelephone(String telephone) {
450	        try {
451	            return normalizeTelephone(telephone);
452	        } catch (ResponseStatusException ex) {
453	            return telephone;
454	        }
455	    }
456	
457	    /**
458	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
459	     * containing at least one dot, none of the three sections containing whitespace or an
460	     * additional {@code @}.
461	     */
462	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
463	
464	    /**
465	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
466	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
467	     * value is then stored and returned lower-cased.
468	     *
469	     * @param email the raw email value supplied by the client, possibly {@code null}
470	     * @return the lower-cased email, or {@code null} when none was supplied
471	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
472	     *                                 is not a syntactically valid address
473	     */
474	    private static String normalizeEmail(String email) {
475	        if (email == null) {
476	            return null;
477	        }
478	        if (!EMAIL_PATTERN.matcher(email).matches()) {
479	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
480	                "email must be a syntactically valid address");
481	        }
482	        return email.toLowerCase(Locale.ROOT);
483	    }
484	
485	    /**
486	     * Common street-type abbreviations expanded to their full word during address normalization.
487	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
488	     */
489	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
490	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
491	
492	    /**
493	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
494	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
495	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
496	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
497	     * address comparison (household duplicate detection and the shared household id).
498	     *
499	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
500	     *
501	     * @param address the raw address supplied by the client, possibly {@code null}
502	     * @return the normalized address
503	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
504	     *                                 after normalization (required field)
505	     */
506	    private static String normalizeAddress(String address) {
507	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
508	        if (collapsed.isEmpty()) {
509	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
510	                "address must not be blank");
511	        }
512	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
513	        StringBuilder normalized = new StringBuilder();
514	        for (int i = 0; i < tokens.length; i++) {
515	            if (i > 0) {
516	                normalized.append(' ');
517	            }
518	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
519	        }
520	        return normalized.toString();
521	    }
522	
523	    /**
524	     * Determines whether the given normalized E.164 telephone is already used by any owner other
525	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
526	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
527	     * inputs representing the same number are treated as duplicates.
528	     *
529	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
530	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
531	     * @return {@code true} if another owner already uses the telephone
532	     */
533	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
534	        for (Owner existing : this.clinicService.findAllOwners()) {
535	            if (excludeId != null && excludeId.equals(existing.getId())) {
536	                continue;
537	            }
538	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
539	                return true;
540	            }
541	        }
542	        return false;
543	    }
544	
545	    /**
546	     * Determines whether the given (already normalized, lower-cased) email is already used by any
547	     * owner other than the one identified by {@code excludeId} (pass {@code null} to consider every
548	     * owner, e.g. on create). Stored emails are compared case-insensitively, so two addresses that
549	     * differ only in letter case are treated as duplicates. A {@code null} email never matches, as
550	     * email is optional.
551	     *
552	     * @param normalizedEmail the already-normalized lower-cased email to look for, or {@code null}
553	     * @param excludeId       id of an owner to ignore during the check, or {@code null} for none
554	     * @return {@code true} if another owner already uses the email
555	     */
556	    private boolean isEmailInUse(String normalizedEmail, Integer excludeId) {
557	        if (normalizedEmail == null) {
558	            return false;
559	        }
560	        for (Owner existing : this.clinicService.findAllOwners()) {
561	            if (excludeId != null && excludeId.equals(existing.getId())) {
562	                continue;
563	            }
564	            String existingEmail = existing.getEmail();
565	            if (existingEmail != null && normalizedEmail.equalsIgnoreCase(existingEmail)) {
566	                return true;
567	            }
568	        }
569	        return false;
570	    }
571	
572	}
