     * lower-cased email (empty when none) and the household id (empty when none), joined with
     * {@code '|'}. This single derived key subsumes what used to be separate telephone, email and
     * household duplicate checks: two owners are duplicates only when their whole identity keys are
     * equal. Because the telephone is part of the key, two members of the same household (same
     * {@code householdId}) with different telephones have different keys and are both allowed.
     *
     * @param owner the owner whose (already normalized) fields form the key
     * @return the identity key
     */
    private String identityKeyFor(Owner owner) {
        return identityKey(toComparableTelephone(owner.getTelephone()),
            owner.getEmail(), owner.getHouseholdId());
    }

