     * Assembles an identity key from its three normalized parts, treating a {@code null} email or
     * household id as empty so the key is always three {@code '|'}-joined segments.
     */
    private static String identityKey(String normalizedTelephone, String email, String householdId) {
        return normalizedTelephone + "|"
            + (email == null ? "" : email) + "|"
            + (householdId == null ? "" : householdId);
    }

    /**
